App;

function App() {
  const [hasPermission, setHasPermission] = useState(false);
  const [postureScore, setPostureScore] = useState<number | null>(null);
  const [postureIssues, setPostureIssues] = useState<string[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [sessionStartTime, setSessionStartTime] = useState<Date | null>(null);
  const [sessionDuration, setSessionDuration] = useState(0);
  const [dailyScores, setDailyScores] = useState<number[]>([]);

  const openAI = new OpenAIService(CONFIG.OPENAI_API_KEY);

  useEffect(() => {
    // Запрос разрешения на использование камеры
    const getCameraPermission = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: true });
        setHasPermission(true);
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (error) {
        console.error('Ошибка получения доступа к камере:', error);
      }
    };

    getCameraPermission();

    // Загрузка ежедневных оценок из localStorage
    const storedScores = localStorage.getItem('dailyScores');
    if (storedScores) {
      setDailyScores(JSON.parse(storedScores));
    }
  }, []);

  useEffect(() => {
    let intervalId: NodeJS.Timeout;

    if (hasPermission) {
      intervalId = setInterval(() => {
        analyzePosture();
      }, 60000); // Анализ каждые 60 секунд
    }

    return () => clearInterval(intervalId);
  }, [hasPermission]);

  useEffect(() => {
    let intervalId: NodeJS.Timeout;

    if (sessionStartTime) {
      intervalId = setInterval(() => {
        const now = new Date();
        setSessionDuration(Math.floor((now.getTime() - sessionStartTime.getTime()) / 1000));
      }, 1000);
    }

    return () => clearInterval(intervalId);
  }, [sessionStartTime]);

  const analyzePosture = async () => {
    if (!videoRef.current || !canvasRef.current) return;

    setIsAnalyzing(true);
    const video = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    ctx?.drawImage(video, 0, 0, canvas.width, canvas.height);

    const imageData = canvas.toDataURL('image/jpeg');

    const result = await openAI.analyzePosture(imageData);

    if (result) {
      setPostureScore(result.score);
      setPostureIssues(result.issues);

      // Сохранение оценки в localStorage
      setDailyScores(prevScores => {
        const newScores = [...prevScores, result.score];
        localStorage.setItem('dailyScores', JSON.stringify(newScores));
        return newScores;
      });

      if (result.score < 60) {
        // Отправка уведомления
        if (Notification.permission === 'granted') {
          new Notification('Внимание!', { body: 'Ваша осанка ухудшилась!' });
        } else if (Notification.permission !== 'denied') {
          Notification.requestPermission().then(permission => {
            if (permission === 'granted') {
              new Notification('Внимание!', { body: 'Ваша осанка ухудшилась!' });
            }
          });
        }
      }
    }
    setIsAnalyzing(false);
  };

  const startSession = () => {
    setSessionStartTime(new Date());
  };

  const endSession = () => {
    setSessionStartTime(null);
    setSessionDuration(0);
  };

  const formatTime = (seconds: number): string => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const remainingSeconds = seconds % 60;
    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${remainingSeconds.toString().padStart(2, '0')}`;
  };

  return (
    <div style={{ fontFamily: 'Arial, sans-serif', padding: '20px' }}>
      <h1>AI Posture Coach</h1>

      {!hasPermission ? (
        <p>Требуется разрешение на использование камеры.</p>
      ) : (
        <>
          <video ref={videoRef} autoPlay style={{ width: '320px', height: '240px', backgroundColor: 'black' }} />
          <canvas ref={canvasRef} style={{ display: 'none' }} />

          {sessionStartTime ? (
            <div>
              <p>Время сессии: {formatTime(sessionDuration)}</p>
              <button onClick={endSession} style={{ padding: '8px 16px', backgroundColor: '#f44336', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>Завершить сессию</button>
            </div>
          ) : (
            <button onClick={startSession} style={{ padding: '8px 16px', backgroundColor: '#4CAF50', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>Начать сессию</button>
          )}

          {isAnalyzing ? (
            <p>Анализ...</p>
          ) : (
            <>
              {postureScore !== null && (
                <div>
                  <p>Оценка осанки: {postureScore}</p>
                  {postureIssues.length > 0 && (
                    <div>
                      <p>Проблемы с осанкой:</p>
                      <ul>
                        {postureIssues.map((issue, index) => (
                          <li key={index}>{issue}</li>
                        ))}
                      </ul>
                    </div>
                  )}
                </div>
              )}
            </>
          )}

          <div>
            <p>Ежедневные оценки:</p>
            <ul>
              {dailyScores.map((score, index) => (
                <li key={index}>Оценка {index + 1}: {score}</li>
              ))}
            </ul>
          </div>
        </>
      )}
    </div>
  );
}

