/**
 * OpenAI Vision Service - Posture Analysis
 * 
 * @description Analyzes webcam snapshots using OpenAI Vision API to detect
 *              posture issues and calculate a health score (0-100).
 *              Includes mock fallback for development without API keys.
 * 
 * @example
 * const result = await analyzePosture(base64Image);
 * console.log(result.score); // 75
 * console.log(result.issues); // ['neck_forward', 'shoulders_raised']
 */


/**
 * Analyzes a base64-encoded image for posture issues
 * @param base64Image - Base64 encoded image data (data:image/jpeg;base64,...)
 * @returns Promise
 */
async function analyzePosture(base64Image) {
  // Check if OpenAI API key is configured
  const isApiKeyConfigured = CONFIG.OPENAI_API_KEY?.startsWith('sk-') && !CONFIG.OPENAI_API_KEY.includes('REPLACE_ME');

  if (!isApiKeyConfigured) {
    // Return mock data for development
    console.warn('OpenAI API key not configured. Using mock data.');
    return getMockPostureAnalysis();
  }

  try {
    const prompt = `Analyze this person's posture from a webcam snapshot. Return ONLY a valid JSON object with no markdown formatting.

    Required JSON structure:
    {
      "score": number (0-100, higher is better posture),
      "issues": string[] (list of detected issues like "neck_forward", "shoulders_raised", "slouching", "asymmetric_shoulders"),
      "message": string (brief descriptive message about posture)
    }

    Scoring guidelines:
    - 90-100: Excellent posture
    - 70-89: Good posture with minor issues
    - 50-69: Fair posture, needs improvement
    - 30-49: Poor posture, significant issues
    - 0-29: Critical posture, immediate attention needed

    Common issues to detect:
    - neck_forward: Head positioned forward of shoulders
    - shoulders_raised: Shoulders elevated toward ears
    - slouching: Upper back rounded, shoulders forward
    - asymmetric_shoulders: One shoulder higher than the other
    - tilted_head: Head tilted to one side

    Be specific and accurate in your assessment.`;

    const requestBody = {
      model: 'gpt-4o-mini',
      messages: [
        {
          role: 'system',
          content: [
            { type: 'text', text: prompt }
          ]
        },
        {
          role: 'user',
          content: [
            { type: 'text', text: 'Please analyze this image for posture issues.' },
            { type: 'image_url', image_url: { url: base64Image } }
          ]
        }
      ]
    };

    const response = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${CONFIG.OPENAI_API_KEY}`
      },
      body: JSON.stringify(requestBody)
    });

    if (!response.ok) {
      throw new Error(`OpenAI API error: ${response.status} ${response.statusText}`);
    }

    const data = await response.json();
    const content = data.choices[0]?.message?.content || '';

    // Parse the JSON response
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      return {
        score: parsed.score || 50,
        issues: parsed.issues || [],
        message: parsed.message || 'Posture analysis complete',
        timestamp: new Date().toISOString()
      };
    }

    throw new Error('Failed to parse OpenAI response');

  } catch (error) {
    console.error('OpenAI Vision analysis error:', error);
    // Return mock data on error
    return getMockPostureAnalysis();
  }
}

/**
 * Generates mock posture analysis data for development
 * @returns PostureAnalysisResult with random but realistic data
 */
function getMockPostureAnalysis() {
  const issues = [
    'neck_forward',
    'shoulders_raised',
    'slouching',
    'asymmetric_shoulders',
    'tilted_head'
  ];

  const issueCount = Math.floor(Math.random() * 3);
  const selectedIssues = [];
  const availableIssues = [...issues];

  for (let i = 0; i < issueCount; i++) {
    if (availableIssues.length === 0) break;
    const index = Math.floor(Math.random() * availableIssues.length);
    selectedIssues.push(availableIssues[index]);
    availableIssues.splice(index, 1);
  }

  const score = Math.floor(Math.random() * 50) + 50; // 50-99
  const messages = [
    'Your posture is good today!',
    'Try to sit up straighter',
    'Take a break and stretch',
    'Your shoulders are too raised',
    'Watch out for neck forward posture',
    'Great job maintaining good posture!'
  ];

  return {
    score,
    issues: selectedIssues,
    message: messages[Math.floor(Math.random() * messages.length)],
    timestamp: new Date().toISOString()
  };
}

/**
 * Converts HTMLVideoElement to base64 image
 * @param videoElement - Video element to capture from
 * @param format - Image format
 * @param quality - JPEG quality (0-1)
 * @returns Promise - Base64 encoded image
 */
function captureFrame(videoElement, format = 'image/jpeg', quality = 0.8) {
  return new Promise((resolve, reject) => {
    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoElement.videoWidth;
      canvas.height = videoElement.videoHeight;
      const ctx = canvas.getContext('2d');

      if (!ctx) {
        reject(new Error('Could not get canvas context'));
        return;
      }

      ctx.drawImage(videoElement, 0, 0, canvas.width, canvas.height);
      const base64 = canvas.toDataURL(format, quality);
      resolve(base64);
    } catch (error) {
      reject(error);
    }
  });
}

/**
 * Checks if browser supports Web Speech API for notifications
 * @returns boolean
 */
function hasNotificationSupport() {
  return 'Notification' in window && Notification.permission !== 'denied';
}

/**
 * Requests notification permission
 * @returns Promise
 */
async function requestNotificationPermission() {
  if (!('Notification' in window)) {
    return false;
  }

  if (Notification.permission === 'granted') {
    return true;
  }

  if (Notification.permission !== 'denied') {
    const permission = await Notification.requestPermission();
    return permission === 'granted';
  }

  return false;
}

/**
 * Sends a browser notification
 * @param title - Notification title
 * @param options - Notification options
 */
function sendNotification(title, options) {
  if (!hasNotificationSupport()) {
    return;
  }

  if (Notification.permission === 'granted') {
    new Notification(title, options);
  }
}

