interface Coin {
  id: string;
  name: string;
  ticker: string;
  quantity: number;
  price: number;
  change24h: number;
  sparkline: [number, number][];
  tip: string;
}

interface SearchResult {
  id: string;
  symbol: string;
  name: string;
}

const MAX_COINS = 5;
const REFRESH_INTERVAL = 30000; // 30 seconds

function App() {
  const [coins, setCoins] = useState<Coin[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Load from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('cryptoTracker_coins');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCoins(parsed);
      } catch (e) {
        console.error('Failed to parse saved coins:', e);
      }
    }
  }, []);

  // Save to localStorage whenever coins change
  useEffect(() => {
    localStorage.setItem('cryptoTracker_coins', JSON.stringify(coins));
  }, [coins]);

  // Auto-refresh interval
  useEffect(() => {
    const interval = setInterval(() => {
      if (coins.length > 0) {
        refreshPrices();
      }
    }, REFRESH_INTERVAL);

    return () => clearInterval(interval);
  }, [coins]);

  // Debounced search
  useEffect(() => {
    if (searchQuery.length < 2) {
      setSearchResults([]);
      return;
    }

    setIsSearching(true);
    const timer = setTimeout(async () => {
      try {
        const results = await fetchSearchResults(searchQuery);
        setSearchResults(results);
      } catch (e) {
        console.error('Search failed:', e);
      } finally {
        setIsSearching(false);
      }
    }, 300);

    return () => clearTimeout(timer);
  }, [searchQuery]);

  const fetchSearchResults = async (query: string): Promise<SearchResult[]> => {
    try {
      const response = await fetch(
        `https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&order=market_cap_desc&per_page=20&page=1&sparkline=false&price_change_percentage=24h`,
        { signal: AbortSignal.timeout(10000) }
      );

      if (!response.ok) throw new Error('Search failed');

      const data = await response.json();
      return data
        .filter((coin: any) =>
          coin.name.toLowerCase().includes(query.toLowerCase()) ||
          coin.symbol.toLowerCase().includes(query.toLowerCase())
        )
        .slice(0, 10)
        .map((coin: any) => ({
          id: coin.id,
          symbol: coin.symbol,
          name: coin.name,
        }));
    } catch (e) {
      return getMockSearchResults(query);
    }
  };

  const getMockSearchResults = (query: string): SearchResult[] => {
    const mock: SearchResult[] = [
      { id: 'bitcoin', symbol: 'btc', name: 'Bitcoin' },
      { id: 'ethereum', symbol: 'eth', name: 'Ethereum' },
      { id: 'solana', symbol: 'sol', name: 'Solana' },
      { id: 'cardano', symbol: 'ada', name: 'Cardano' },
      { id: 'ripple', symbol: 'xrp', name: 'XRP' },
    ];
    return mock.filter(
      coin =>
        coin.name.toLowerCase().includes(query.toLowerCase()) ||
        coin.symbol.toLowerCase().includes(query.toLowerCase())
    );
  };

  const refreshPrices = async () => {
    setIsRefreshing(true);
    setError(null);

    try {
      const coinIds = coins.map(c => c.id);
      const response = await fetch(
        `https://api.coingecko.com/api/v3/simple/price?ids=${coinIds.join(
          ','
        )}&vs_currencies=usd&include_24h_change=true&include_7d_price_change=false`,
        { signal: AbortSignal.timeout(15000) }
      );

      if (!response.ok) throw new Error('Price fetch failed');

      const data = await response.json();

      const updatedCoins = coins.map(coin => {
        const priceData = data[coin.id];
        if (!priceData) return coin;

        return {
          ...coin,
          price: priceData.usd,
          change24h: priceData.usd_24h_change,
        };
      });

      setCoins(updatedCoins);
    } catch (e) {
      setError('Failed to refresh prices. Using cached data.');
      console.error('Refresh failed:', e);
    } finally {
      setIsRefreshing(false);
    }
  };

  const addCoin = (result: SearchResult) => {
    if (coins.length >= MAX_COINS) {
      setError(`Maximum ${MAX_COINS} coins allowed`);
      setTimeout(() => setError(null), 3000);
      return;
    }

    const newCoin: Coin = {
      id: result.id,
      name: result.name,
      ticker: result.symbol.toUpperCase(),
      quantity: 0,
      price: 0,
      change24h: 0,
      sparkline: [],
      tip: getBeginnerTip(result.id),
    };

    setCoins([...coins, newCoin]);
    setSearchQuery('');
    setSearchResults([]);
  };

  const removeCoin = (coinId: string) => {
    setCoins(coins.filter(c => c.id !== coinId));
  };

  const updateQuantity = (coinId: string, quantity: number) => {
    setCoins(
      coins.map(c => (c.id === coinId ? { ...c, quantity: Math.max(0, quantity) } : c))
    );
  };

  const getSparklinePath = useCallback((prices: [number, number][]) => {
    if (prices.length < 2) return '';

    const width = 100;
    const height = 40;
    const minPrice = Math.min(...prices.map(p => p[1]));
    const maxPrice = Math.max(...prices.map(p => p[1]));
    const range = maxPrice - minPrice || 1;

    const points = prices.map((p, i) => {
      const x = (i / (prices.length - 1)) * width;
      const y = height - ((p[1] - minPrice) / range) * height;
      return `${x},${y}`;
    });

    return `M${points.join(' L')}`;
  }, []);

  const portfolioValue = useMemo(() => {
    return coins.reduce((sum, coin) => sum + coin.price * coin.quantity, 0);
  }, [coins]);

  const portfolio24hChange = useMemo(() => {
    if (portfolioValue === 0) return 0;

    const weightedChange = coins.reduce((sum, coin) => {
      const value = coin.price * coin.quantity;
      return sum + (value * coin.change24h) / 100;
    }, 0);

    return (weightedChange / portfolioValue) * 100;
  }, [coins, portfolioValue]);

  const getTip = (coinId: string): string => {
    const tips: Record<string, string> = {
      bitcoin: 'Bitcoin (BTC) is the most liquid cryptocurrency with the highest market cap. Great for beginners starting their portfolio.',
      ethereum: 'Ethereum (ETH) powers smart contracts and DeFi. Consider it the "oil" of the crypto ecosystem.',
      cardano: 'Cardano (ADA) focuses on sustainability and peer-reviewed research. Known for strong security.',
      solana: 'Solana (SOL) offers fast transactions with low fees. Popular for NFTs and DeFi applications.',
      polkadot: 'Polkadot (DOT) enables different blockchains to interoperate. A key infrastructure play.',
      ripple: 'XRP (XRP) is designed for cross-border payments. Often used by financial institutions.',
      dogecoin: 'Dogecoin (DOGE) started as a meme but gained serious adoption. High volatility, high fun.',
      chainlink: 'Chainlink (LINK) provides real-world data to smart contracts. Critical DeFi infrastructure.',
      litecoin: 'Litecoin (LTC) is often called "silver to Bitcoin's gold". Faster transactions, lower fees.',
      uniswap: 'Uniswap (UNI) is the leading decentralized exchange token. Essential for DeFi trading.',
    };
    return tips[coinId] || 'This coin has strong fundamentals. Always do your own research before investing.';
  };

  return (
    <div style={{ fontFamily: 'system-ui, -apple-system, sans-serif', backgroundColor: '#0f0f23', minHeight: '100vh', color: '#ffffff', padding: '16px' }}>
      <style>{`
        @keyframes pulse {
          0%, 100% { opacity: 1; }
          50% { opacity: 0.7; }
        }
        .pulse { animation: pulse 2s ease-in-out infinite; }
        @keyframes slideDown {
          from { opacity: 0; transform: translateY(-10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .slide-down { animation: slideDown 0.3s ease-out; }
      `}</style>

      <div style={{ maxWidth: '600px', margin: '0 auto' }}>
        {/* Header */}
        <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
          <h1 style={{ fontSize: '28px', fontWeight: 'bold', margin: 0 }}>Crypto Micro-Tracker</h1>
          <button
            onClick={refreshPrices}
            disabled={isRefreshing}
            style={{
              padding: '8px 16px',
              borderRadius: '8px',
              border: 'none',
              backgroundColor: isRefreshing ? '#4a4a6a' : '#6366f1',
              color: '#ffffff',
              cursor: isRefreshing ? 'not-allowed' : 'pointer',
              fontSize: '14px',
              fontWeight: '500',
              transition: 'all 0.2s',
            }}
          >
            {isRefreshing ? 'Refreshing...' : 'Refresh'}
          </button>
        </header>

        {/* Portfolio Summary */}
        <div style={{ backgroundColor: '#1a1a3e', borderRadius: '12px', padding: '20px', marginBottom: '24px' }}>
          <div style={{ fontSize: '14px', color: '#a0a0c0', marginBottom: '4px' }}>Portfolio Value</div>
          <div style={{ fontSize: '32px', fontWeight: 'bold', marginBottom: '8px' }}>
            ${portfolioValue.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <span
              style={{
                fontSize: '16px',
                fontWeight: '600',
                color: portfolio24hChange >= 0 ? '#10b981' : '#ef4444',
              }}
            >
              {portfolio24hChange >= 0 ? '+' : ''}
              {portfolio24hChange.toFixed(2)}%
            </span>
            <span style={{ fontSize: '14px', color: '#a0a0c0' }}>24h</span>
          </div>
        </div>

        {/* Add Coin Search */}
        <div style={{ marginBottom: '24px' }}>
          <div style={{ position: 'relative' }}>
            <input
              type="text"
              value={searchQuery}
              onChange={e = /> setSearchQuery(e.target.value)}
              placeholder="Search coins (e.g., Bitcoin, BTC)..."
              style={{
                width: '100%',
                padding: '12px 16px',
                borderRadius: '12px',
                border: '2px solid #2a2a4e',
                backgroundColor: '#1a1a3e',
                color: '#ffffff',
                fontSize: '16px',
                outline: 'none',
                boxSizing: 'border-box',
              }}
            />
            {isSearching && (
              <div
                style={{
                  position: 'absolute',
                  right: '16px',
                  top: '50%',
                  transform: 'translateY(-50%)',
                  width: '20px',
