// Типы данных
interface MoodEntry {
  id: string;
  mood: number;
  moodLabel: string;
  note: string;
  timestamp: string;
  tags: string[];
}

interface MoodStats {
  totalEntries: number;
  averageMood: number;
  moodDistribution: { [key: number]: number };
  streak: number;
  bestMood: number;
  worstMood: number;
}

// Константы настроения
const MOODS = [
  { value: 5, label: 'Отлично', icon: <Sun size={24} />, color: 'bg-green-500', textColor: 'text-green-500' },
  { value: 4, label: 'Хорошо', icon: <Smile size={24} />, color: 'bg-blue-500', textColor: 'text-blue-500' },
  { value: 3, label: 'Нормально', icon: <Meh size={24} />, color: 'bg-yellow-500', textColor: 'text-yellow-500' },
  { value: 2, label: 'Плохо', icon: <Frown size={24} />, color: 'bg-orange-500', textColor: 'text-orange-500' },
  { value: 1, label: 'Ужасно', icon: <CloudRain size={24} />, color: 'bg-gray-500', textColor: 'text-gray-500' },
];

// Сервис работы с localStorage
const MoodService = {
  STORAGE_KEY: 'mood_tracker_entries',

  getEntries(): MoodEntry[] {
    try {
      const data = localStorage.getItem(this.STORAGE_KEY);
      return data ? JSON.parse(data) : [];
    } catch (error) {
      console.error('Ошибка чтения из localStorage:', error);
      return [];
    }
  },

  saveEntry(entry: MoodEntry): void {
    try {
      const entries = this.getEntries();
      entries.unshift(entry);
      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(entries));
    } catch (error) {
      console.error('Ошибка записи в localStorage:', error);
    }
  },

  deleteEntry(id: string): void {
    try {
      const entries = this.getEntries();
      const filtered = entries.filter(e => e.id !== id);
      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(filtered));
    } catch (error) {
      console.error('Ошибка удаления:', error);
    }
  },

  getStats(): MoodStats {
    const entries = this.getEntries();
    if (entries.length === 0) {
      return {
        totalEntries: 0,
        averageMood: 0,
        moodDistribution: {},
        streak: 0,
        bestMood: 0,
        worstMood: 0
      };
    }

    const moodValues = entries.map(e => e.mood);
    const averageMood = moodValues.reduce((sum, val) => sum + val, 0) / moodValues.length;

    const distribution: { [key: number]: number } = {};
    moodValues.forEach(mood => {
      distribution[mood] = (distribution[mood] || 0) + 1;
    });

    // Вычисляем серию дней
    let streak = 0;
    const sortedEntries = [...entries].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    const today = new Date().toDateString();

    if (sortedEntries.length > 0 && new Date(sortedEntries[0].timestamp).toDateString() === today) {
      streak = 1;
      for (let i = 1; i < sortedEntries.length; i++) {
        const prevDate = new Date(sortedEntries[i - 1].timestamp).toDateString();
        const currDate = new Date(sortedEntries[i].timestamp).toDateString();
        const prevDay = new Date(prevDate);
        const currDay = new Date(currDate);
        const diffDays = Math.floor((prevDay.getTime() - currDay.getTime()) / (1000 * 60 * 60 * 24));
        if (diffDays === 1) {
          streak++;
        } else {
          break;
        }
      }
    }

    return {
      totalEntries: entries.length,
      averageMood: Math.round(averageMood * 10) / 10,
      moodDistribution: distribution,
      streak,
      bestMood: Math.max(...moodValues),
      worstMood: Math.min(...moodValues)
    };
  }
};

// Компонент выбора настроения
function MoodSelector({ onSelect }: { onSelect: (mood: number, note: string) => void }) {
  const [selectedMood, setSelectedMood] = useState<number | null>(null);
  const [note, setNote] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [showTags, setShowTags] = useState(false);

  const tagOptions = ['Работа', 'Семья', 'Друзья', 'Спорт', 'Отдых', 'Хобби', 'Путешествия', 'Еда'];

  const toggleTag = (tag: string) => {
    setTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
  };

  const handleSubmit = () => {
    if (selectedMood !== null) {
      onSelect(selectedMood, note);
      setSelectedMood(null);
      setNote('');
      setTags([]);
    }
  };

  return (
    <div className="space-y-6">
      <div className="text-center mb-8">
        <h2 className="text-3xl font-bold text-gray-900 mb-2">Как вы себя чувствуете?</h2>
        <p className="text-gray-600">Выберите своё текущее настроение</p>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        {MOODS.map((mood) => (
          <button
            key={mood.value}
            onClick={() => setSelectedMood(mood.value)}
            className={`p-6 rounded-2xl transition-all ${
              selectedMood === mood.value
                ? `${mood.color} text-white shadow-xl scale-110`
                : 'bg-white text-gray-700 hover:shadow-lg hover:scale-105'
            }`}
          >
            <div className="mb-3">{mood.icon}</div>
            <div className="font-semibold">{mood.label}</div>
          </button>
        ))}
      </div>

      {selectedMood !== null && (
        <div className="bg-white rounded-2xl p-6 shadow-lg space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Добавьте заметку (опционально)</label>
            <textarea
              value={note}
              onChange={(e) => setNote(e.target.value)}
              placeholder="Что произошло сегодня? Что повлияло на ваше настроение?"
              className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none"
              rows={3}
            />
          </div>

          <div>
            <button
              onClick={() => setShowTags(!showTags)}
              className="flex items-center gap-2 text-sm text-gray-600 hover:text-gray-900"
            >
              <Star size={16} />
              Добавить теги
            </button>
            {showTags && (
              <div className="flex flex-wrap gap-2 mt-3">
                {tagOptions.map((tag) => (
                  <button
                    key={tag}
                    onClick={() => toggleTag(tag)}
                    className={`px-3 py-1 rounded-full text-sm transition-colors ${
                      tags.includes(tag)
                        ? 'bg-blue-500 text-white'
                        : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                    }`}
                  >
                    {tag}
                  </button>
                ))}
              </div>
            )}
          </div>

          <button
            onClick={handleSubmit}
            className="w-full bg-gradient-to-r from-blue-500 to-purple-600 text-white py-4 rounded-xl font-semibold hover:from-blue-600 hover:to-purple-700 transition-all shadow-lg"
          >
            Сохранить настроение
          </button>
        </div>
      )}
    </div>
  );
}

