      const updatedCoins = coins.map(coin => {
        const priceInfo = pricesData[coin.id] || {};
        const history = chartDataPromises.find(h => h && h.length > 0); // Simplified: in real app, map properly

        // Re-fetch history for each coin individually for accuracy
        return {
          ...coin,
          price: priceInfo.usd || 0,
          change24h: priceInfo.usd_24h_change || 0,
          // Note: In a real app, we'd map history correctly. 
