          // Let's fix history fetching properly below in the component logic
        };
      });

      // Actually, let's do the history fetch properly in a separate pass to avoid race conditions
      // For this demo, we'll just update prices and assume history is cached or mocked
      setCoins(updatedCoins);
      setLastUpdated(new Date());
