                      transition: 'background-color 0.2s'
                    }}
                    onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f9fafb'}
                    onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'transparent'}
                  >
                    <span style={{ fontWeight: '500' }}>{coin.name} <span style={{ color: '#9ca3af', fontSize: '14px' }}>({coin.symbol.toUpperCase()})</span></span>
                    <span style={{ color: '#3b82f6', fontSize: '14px' }}>Add +</span>
                  </button>
                ))}
              </div>
            )}
          </div>
        ) : (
          coins.map(coin => (
            <div 
              key={coin.id} 
              className="card-shadow"
              style={{
                backgroundColor: '#fff',
                borderRadius: '12px',
                padding: '16px',
                position: 'relative',
                transition: 'transform 0.2s'
              }}
            >
              {/* Remove Button */}
              <button
                onClick={() => removeCoin(coin.id)}
                style={{
                  position: 'absolute',
                  top: '8px',
                  right: '8px',
                  background: '#fee2e2',
                  color: '#ef4444',
                  border: 'none',
                  borderRadius: '50%',
                  width: '24px',
                  height: '24px',
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontSize: '12px',
                  fontWeight: 'bold'
                }}
                title="Remove coin"
              >
                ×
              </button>

              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '12px' }}>
                <div>
                  <h2 style={{ fontSize: '20px', fontWeight: 'bold', margin: '0 0 4px 0' }}>
                    {coin.name}
                  </h2>
                  <span style={{ 
                    backgroundColor: '#e5e7eb', 
                    color: '#374151', 
                    padding: '2px 8px', 
                    borderRadius: '4px', 
                    fontSize: '12px',
                    fontWeight: '600'
                  }}>
                    {coin.symbol.toUpperCase()}
                  </span>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <div style={{ fontSize: '24px', fontWeight: 'bold' }}>
                    ${coin.price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                  </div>
                  <div style={{ 
                    fontSize: '14px', 
                    fontWeight: '600',
                    color: coin.change24h >= 0 ? '#10b981' : '#ef4444'
                  }}>
                    {coin.change24h >= 0 ? '+' : ''}{coin.change24h.toFixed(2)}%
                  </div>
                </div>
              </div>

              {/* Sparkline */}
              <div style={{ marginBottom: '12px' }}>
                <Sparkline 
                  data={coin.history} 
                  color={coin.change24h >= 0 ? '#10b981' : '#ef4444'} 
                />
              </div>

              {/* Quantity Input */}
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '8px' }}>
                <label style={{ fontSize: '14px', color: '#6b7280', fontWeight: '500' }}>
                  Quantity:
                </label>
                <input
                  type="number"
                  value={coin.quantity || ''}
                  onChange={(e) = /> updateQuantity(coin.id, e.target.value)}
                  placeholder="0"
                  min="0"
                  step="any"
                  style={{
                    padding: '8px 12px',
                    borderRadius: '6px',
                    border: '1px solid #d1d5db',
                    width: '100px',
                    fontSize: '14px'
                  }}
                />
                <span style={{ fontSize: '14px', color: '#6b7280' }}>
                  = ${(coin.price * (coin.quantity || 0)).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                </span>
              </div>

              {/* Tip */}
              <TipBanner coinId={coin.id} />
            </div>
          ))
        )}
      </main>

      {/* Footer Status */}
      <footer style={{ 
        maxWidth: '800px', 
        margin: '24px auto 0', 
        textAlign: 'center', 
        color: '#9ca3af', 
        fontSize: '12px' 
      }}>
        {lastUpdated && (
          <div style={{ marginBottom: '8px' }}>
            Last updated: {lastUpdated.toLocaleTimeString()}
            {isLoading && <span className="pulse" style={{ marginLeft: '8px' }}>●</span>}
          </div>
        )}
        <div>
          Data provided by CoinGecko API • Auto-refresh every 30s
        </div>
        {error && (
          <div style={{ color: '#ef4444', marginTop: '8px' }}>
            Error: {error}
          </div>
        )}
      </footer>
    </div>
  );
}

const SETTINGS = {
  settings: ['Fantasy', 'Sci-Fi', 'Horror', 'Cyberpunk'],
  tones: ['Epic', 'Comedic', 'Dark', 'Mystery'],
  difficulties: ['Easy', 'Medium', 'Hard', 'Deadly'],
};

const RARITY_COLORS = {
  Common: '#9ca3af',
  Uncommon: '#4ade80',
  Rare: '#60a5fa',
  Legendary: '#fbbf24',
};

function App() {
  const [partySize, setPartySize] = useState(4);
  const [setting, setSetting] = useState('Fantasy');
  const [tone, setTone] = useState('Epic');
  const [difficulty, setDifficulty] = useState('Medium');
  const [isLoading, setIsLoading] = useState(false);
  const [quest, setQuest] = useState(null);
  const [error, setError] = useState(null);

  const handleGenerate = async () => {
    setIsLoading(true);
    setError(null);
    setQuest(null);

    try {
      const result = await generateDnDQuest({
        partySize,
        setting,
        tone,
        difficulty,
      });

      if (result) {
        setQuest(result);
      } else {
        setError('Failed to generate quest. Please try again.');
      }
    } catch (err) {
      setError('An error occurred. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleCopy = () => {
    if (!quest) return;
    const text = `
${quest.quest_title}
${'='.repeat(quest.quest_title.length)}

HOOK: ${quest.hook_paragraph}

ACT I - SETUP: ${quest.act_setup}

ACT II - CONFRONTATION: ${quest.act_confrontation}

ACT III - RESOLUTION: ${quest.act_resolution}

NPCs:
- ${quest.npc_1_name}: ${quest.npc_1_motivation} (Secret: ${quest.npc_1_secret})
- ${quest.npc_2_name}: ${quest.npc_2_motivation} (Secret: ${quest.npc_2_secret})
- ${quest.npc_3_name}: ${quest.npc_3_motivation} (Secret: ${quest.npc_3_secret})

LOCATIONS:
- ${quest.location_1_name}: ${quest.location_1_description}
  Encounter: ${quest.location_1_encounter}
- ${quest.location_2_name}: ${quest.location_2_description}
  Encounter: ${quest.location_2_encounter}

LOOT:
- ${quest.loot_item_1} (${quest.loot_item_1_rarity})
- ${quest.loot_item_2} (${quest.loot_item_2_rarity})
- ${quest.loot_item_3} (${quest.loot_item_3_rarity})

TWIST: ${quest.twist_ending}
    `.trim();
    navigator.clipboard.writeText(text);
    alert('Quest copied to clipboard!');
  };

  const getDifficultyColor = (diff) => {
    const colors = { Easy: '#4ade80', Medium: '#fbbf24', Hard: '#f87171', Deadly: '#ef4444' };
    return colors[diff] || '#9ca3af';
  };

  return (
    <div style={{
      minHeight: '100vh',
      backgroundColor: '#1a1a2e',
      color: '#e2e8f0',
      fontFamily: 'Georgia, serif',
      padding: '24px',
      boxSizing: 'border-box',
    }}>
      <style>{`
        @media print {
          .no-print { display: none !important; }
          body { background: white !important; color: black !important; }
          .quest-card { box-shadow: none !important; border: 2px solid #000 !important; }
        }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .fade-in { animation: fadeIn 0.4s ease forwards; }
        .loading-spinner {
          border: 4px solid rgba(255,255,255,0.1);
          border-top-color: #4ade80;
          border-radius: 50%;
          width: 40px;
          height: 40px;
          animation: spin 1s linear infinite;
        }
        @keyframes spin { to { transform: rotate(360deg); } }
      `}</style>

      <header style={{ textAlign: 'center', marginBottom: '40px' }}>
        <h1 style={{
          fontSize: '42px',
          fontWeight: 'bold',
          color: '#4ade80',
          margin: '0 0 8px 0',
          textShadow: '0 0 20px rgba(74,222,128,0.3)',
        }}>
          🎲 D&D Quest Generator
        </h1>
        <p style={{ color: '#94a3b8', fontSize: '16px', margin: 0 }}>
          AI-powered quest generation in 10 seconds
        </p>
      </header>

      <div className="no-print" style={{
        maxWidth: '600px',
        margin: '0 auto 40px',
        backgroundColor: '#1e293b',
        padding: '24px',
        borderRadius: '12px',
        border: '1px solid #334155',
      }}>
        <h2 style={{ fontSize: '20px', color: '#e2e8f0', marginBottom: '20px' }}>
          Quest Settings
        </h2>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px', marginBottom: '20px' }}>
          <div>
            <label style={{ display: 'block', marginBottom: '8px', color: '#94a3b8', fontSize: '14px' }}>
              Party Size
            </label>
            <select
              value={partySize}
              onChange={(e) => setPartySize(Number(e.target.value))}
              style={{
                width: '100%',
                padding: '12px',
                backgroundColor: '#0f172a',
                color: '#e2e8f0',
                border: '1px solid #334155',
                borderRadius: '8px',
                fontSize: '16px',
                cursor: 'pointer',
              }}
            >
              {[1, 2, 3, 4, 5, 6].map((n) => (
                <option key={n} value={n}>{n} {n === 1 ? 'Hero' : 'Heroes'}</option>
              ))}
            </select>
          </div>

          <div>
            <label style={{ display: 'block', marginBottom: '8px', color: '#94a3b8', fontSize: '14px' }}>
              Setting
            </label>
            <select
              value={setting}
              onChange={(e) => setSetting(e.target.value)}
              style={{
                width: '100%',
                padding: '12px',
                backgroundColor: '#0f172a',
                color: '#e2e8f0',
                border: '1px solid #334155',
                borderRadius: '8px',
                fontSize: '16px',
