          </div>

          <div>
            <label style={{ display: 'block', marginBottom: '8px', color: '#94a3b8', fontSize: '14px' }}>
              Tone
            </label>
            <select
              value={tone}
              onChange={(e) => setTone(e.target.value)}
              style={{
                width: '100%',
                padding: '12px',
                backgroundColor: '#0f172a',
                color: '#e2e8f0',
                border: '1px solid #334155',
                borderRadius: '8px',
                fontSize: '16px',
                cursor: 'pointer',
              }}
            >
              {SETTINGS.tones.map((t) => (
                <option key={t} value={t}>{t}</option>
              ))}
            </select>
          </div>

          <div>
            <label style={{ display: 'block', marginBottom: '8px', color: '#94a3b8', fontSize: '14px' }}>
              Difficulty
            </label>
            <select
              value={difficulty}
              onChange={(e) => setDifficulty(e.target.value)}
              style={{
                width: '100%',
                padding: '12px',
                backgroundColor: '#0f172a',
                color: '#e2e8f0',
                border: '1px solid #334155',
                borderRadius: '8px',
                fontSize: '16px',
                cursor: 'pointer',
              }}
            >
              {SETTINGS.difficulties.map((d) => (
                <option key={d} value={d}>{d}</option>
              ))}
            </select>
          </div>
        </div>

        <button
          onClick={handleGenerate}
          disabled={isLoading}
          style={{
            width: '100%',
            padding: '16px',
            backgroundColor: '#4ade80',
            color: '#064e3b',
            border: 'none',
            borderRadius: '8px',
            fontSize: '18px',
            fontWeight: 'bold',
            cursor: isLoading ? 'not-allowed' : 'pointer',
            opacity: isLoading ? 0.6 : 1,
            transition: 'all 0.2s',
          }}
        >
          {isLoading ? (
            <span style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '12px' }}>
              <div className="loading-spinner"></div>
              Generating Quest...
            </span>
          ) : (
            '✨ Generate Quest'
          )}
        </button>
      </div>

      {error && (
        <div style={{
          maxWidth: '600px',
          margin: '0 auto 24px',
          padding: '16px',
          backgroundColor: '#ef4444',
          color: 'white',
          borderRadius: '8px',
          textAlign: 'center',
        }}>
          {error}
        </div>
      )}

      {quest && (
        <div className="quest-card fade-in" style={{
          maxWidth: '800px',
          margin: '0 auto',
          backgroundColor: '#1e293b',
          borderRadius: '16px',
          overflow: 'hidden',
          border: '2px solid #4ade80',
        }}>
          <div style={{
            backgroundColor: '#4ade80',
            color: '#064e3b',
            padding: '24px',
            textAlign: 'center',
          }}>
            <h2 style={{ fontSize: '28px', fontWeight: 'bold', margin: '0 0 8px 0' }}>
              {quest.quest_title}
            </h2>
            <div style={{ display: 'flex', justifyContent: 'center', gap: '16px', flexWrap: 'wrap' }}>
              <span style={{
                backgroundColor: getDifficultyColor(difficulty),
                color: '#000',
                padding: '4px 12px',
                borderRadius: '20px',
                fontSize: '14px',
                fontWeight: 'bold',
              }}>
                {difficulty}
              </span>
              <span style={{
                backgroundColor: '#60a5fa',
                color: '#000',
                padding: '4px 12px',
                borderRadius: '20px',
                fontSize: '14px',
                fontWeight: 'bold',
              }}>
                {partySize} Players
              </span>
              <span style={{
                backgroundColor: '#fbbf24',
                color: '#000',
                padding: '4px 12px',
                borderRadius: '20px',
                fontSize: '14px',
                fontWeight: 'bold',
              }}>
                {setting}
              </span>
            </div>
          </div>

          <div style={{ padding: '24px' }}>
            <div style={{
              backgroundColor: '#0f172a',
              padding: '16px',
              borderRadius: '8px',
              marginBottom: '24px',
              borderLeft: '4px solid #4ade80',
            }}>
              <h3 style={{ color: '#4ade80', fontSize: '16px', margin: '0 0 8px 0' }}>🎣 The Hook</h3>
              <p style={{ color: '#e2e8f0', lineHeight: '1.6', margin: 0 }}>
                {quest.hook_paragraph}
              </p>
            </div>

            <div style={{ marginBottom: '24px' }}>
              <h3 style={{ color: '#e2e8f0', fontSize: '20px', marginBottom: '16px', borderBottom: '2px solid #334155', paddingBottom: '8px' }}>
                📖 The Story
              </h3>
              <div style={{ display: 'grid', gap: '16px' }}>
                <div style={{ backgroundColor: '#0f172a', padding: '16px', borderRadius: '8px' }}>
                  <h4 style={{ color: '#60a5fa', fontSize: '16px', margin: '0 0 8px 0' }}>Act I — Setup</h4>
                  <p style={{ color: '#94a3b8', lineHeight: '1.6', margin: 0 }}>{quest.act_setup}</p>
                </div>
                <div style={{ backgroundColor: '#0f172a', padding: '16px', borderRadius: '8px' }}>
                  <h4 style={{ color: '#fbbf24', fontSize: '16px', margin: '0 0 8px 0' }}>Act II — Confrontation</h4>
                  <p style={{ color: '#94a3b8', lineHeight: '1.6', margin: 0 }}>{quest.act_confrontation}</p>
                </div>
                <div style={{ backgroundColor: '#0f172a', padding: '16px', borderRadius: '8px' }}>
                  <h4 style={{ color: '#ef4444', fontSize: '16px', margin: '0 0 8px 0' }}>Act III — Resolution</h4>
                  <p style={{ color: '#94a3b8', lineHeight: '1.6', margin: 0 }}>{quest.act_resolution}</p>
                </div>
              </div>
            </div>

            <div style={{ marginBottom: '24px' }}>
              <h3 style={{ color: '#e2e8f0', fontSize: '20px', marginBottom: '16px', borderBottom: '2px solid #334155', paddingBottom: '8px' }}>
                👥 NPCs
              </h3>
              <div style={{ display: 'grid', gap: '12px' }}>
                {[
                  { name: quest.npc_1_name, motivation: quest.npc_1_motivation, secret: quest.npc_1_secret },
                  { name: quest.npc_2_name, motivation: quest.npc_2_motivation, secret: quest.npc_2_secret },
                  { name: quest.npc_3_name, motivation: quest.npc_3_motivation, secret: quest.npc_3_secret },
                ].map((npc, idx) => (
                  <div key={idx} style={{
                    backgroundColor: '#0f172a',
                    padding: '16px',
