            <div style={{ marginBottom: '24px' }}>
              <h3 style={{ color: '#e2e8f0', fontSize: '20px', marginBottom: '16px', borderBottom: '2px solid #334155', paddingBottom: '8px' }}>
                🗺️ Locations
              </h3>
              <div style={{ display: 'grid', gap: '12px' }}>
                {[
                  { name: quest.location_1_name, desc: quest.location_1_description, encounter: quest.location_1_encounter },
                  { name: quest.location_2_name, desc: quest.location_2_description, encounter: quest.location_2_encounter },
                ].map((loc, idx) => (
                  <div key={idx} style={{
                    backgroundColor: '#0f172a',
                    padding: '16px',
                    borderRadius: '8px',
                    borderLeft: '4px solid #fbbf24',
                  }}>
                    <h4 style={{ color: '#fbbf24', fontSize: '16px', margin: '0 0 8px 0' }}>{loc.name}</h4>
                    <p style={{ color: '#94a3b8', fontSize: '14px', margin: '0 0 4px 0' }}>
                      {loc.desc}
                    </p>
                    <p style={{ color: '#4ade80', fontSize: '14px', margin: 0 }}>
                      <strong>Encounter:</strong> {loc.encounter}
                    </p>
                  </div>
                ))}
              </div>
            </div>

            <div style={{ marginBottom: '24px' }}>
              <h3 style={{ color: '#e2e8f0', fontSize: '20px', marginBottom: '16px', borderBottom: '2px solid #334155', paddingBottom: '8px' }}>
                💎 Loot Table
              </h3>
              <div style={{ display: 'grid', gap: '8px' }}>
                {[
                  { item: quest.loot_item_1, rarity: quest.loot_item_1_rarity },
                  { item: quest.loot_item_2, rarity: quest.loot_item_2_rarity },
                  { item: quest.loot_item_3, rarity: quest.loot_item_3_rarity },
                ].map((loot, idx) => (
                  <div key={idx} style={{
                    backgroundColor: '#0f172a',
                    padding: '12px 16px',
                    borderRadius: '8px',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                  }}>
                    <span style={{ color: '#e2e8f0', fontSize: '16px' }}>{loot.item}</span>
                    <span style={{
                      backgroundColor: RARITY_COLORS[loot.rarity] || '#9ca3af',
                      color: '#000',
                      padding: '4px 12px',
                      borderRadius: '20px',
                      fontSize: '12px',
                      fontWeight: 'bold',
                    }}>
                      {loot.rarity}
                    </span>
                  </div>
                ))}
              </div>
            </div>

            <div style={{
              backgroundColor: '#7c3aed',
              padding: '16px',
              borderRadius: '8px',
              borderLeft: '4px solid #a78bfa',
            }}>
              <h4 style={{ color: '#e9d5ff', fontSize: '16px', margin: '0 0 8px 0' }}>
                🌀 Twist Ending
              </h4>
              <p style={{ color: '#e2e8f0', lineHeight: '1.6', margin: 0 }}>
                {quest.twist_ending}
              </p>
            </div>
          </div>

          <div className="no-print" style={{
            padding: '24px',
            backgroundColor: '#0f172a',
            display: 'flex',
            gap: '12px',
            justifyContent: 'center',
            flexWrap: 'wrap',
          }}>
            <button
              onClick={handleCopy}
              style={{
                padding: '12px 24px',
                backgroundColor: '#334155',
                color: '#e2e8f0',
                border: 'none',
                borderRadius: '8px',
                fontSize: '16px',
                cursor: 'pointer',
                transition: 'background-color 0.2s',
              }}
              onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#475569'}
              onMouseLeave={(e) => e.currentTarget.style.backgroundColor = '#334155'}
            >
              📋 Copy to Clipboard
            </button>
            <button
              onClick={handlePrint}
              style={{
                padding: '12px 24px',
                backgroundColor: '#4ade80',
                color: '#064e3b',
                border: 'none',
                borderRadius: '8px',
                fontSize: '16px',
                fontWeight: 'bold',
                cursor: 'pointer',
                transition: 'background-color 0.2s',
              }}
              onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#22c55e'}
              onMouseLeave={(e) => e.currentTarget.style.backgroundColor = '#4ade80'}
            >
              🖨️ Save as PDF
            </button>
            <button
              onClick={handleGenerate}
              style={{
                padding: '12px 24px',
                backgroundColor: '#60a5fa',
                color: '#000',
                border: 'none',
                borderRadius: '8px',
                fontSize: '16px',
                cursor: 'pointer',
                transition: 'background-color 0.2s',
              }}
              onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#3b82f6'}
              onMouseLeave={(e) => e.currentTarget.style.backgroundColor = '#60a5fa'}
            >
              🔄 Regenerate
            </button>
          </div>
        </div>
      )}

      {!quest && !isLoading && (
        <div style={{
          maxWidth: '400px',
          margin: '40px auto',
          textAlign: 'center',
          color: '#64748b',
        }}>
          <p style={{ fontSize: '64px', marginBottom: '16px' }}>🎲</p>
          <p>Configure your settings and click Generate to create your quest!</p>
        </div>
      )}
    </div>
  );
}

App;

// Mock Lucide icons for standalone environment
