const CoinGeckoService = {
  async getCoinList() {
    try {
      const response = await fetch('https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&order=market_cap_desc&per_page=250&page=1&sparkline=false');
      if (!response.ok) throw new Error('API error');
      return await response.json();
    } catch (error) {
      console.warn('CoinGecko API failed, using mock data');
      return [
        { id: 'bitcoin', symbol: 'btc', name: 'Bitcoin' },
        { id: 'ethereum', symbol: 'eth', name: 'Ethereum' },
        { id: 'solana', symbol: 'sol', name: 'Solana' },
        { id: 'cardano', symbol: 'ada', name: 'Cardano' },
        { id: 'dogecoin', symbol: 'doge', name: 'Dogecoin' },
        { id: 'ripple', symbol: 'xrp', name: 'XRP' },
        { id: 'polkadot', symbol: 'dot', name: 'Polkadot' },
        { id: 'avalanche-2', symbol: 'avax', name: 'Avalanche' },
        { id: 'chainlink', symbol: 'link', name: 'Chainlink' },
        { id: 'polygon', symbol: 'matic', name: 'Polygon' }
      ];
    }
  },

  async getPrices(ids) {
    try {
      const response = await fetch('https://api.coingecko.com/api/v3/simple/price?ids=' + ids.join(',') + '&vs_currencies=usd&include_24h_change=true');
      if (!response.ok) throw new Error('API error');
      return await response.json();
    } catch (error) {
      console.warn('CoinGecko price API failed, using mock data');
      const mock = {};
      ids.forEach(id => {
        const change = (Math.random() * 10 - 5).toFixed(2);
        mock[id] = { usd: Math.random() * 1000 + 10, usd_24h_change: parseFloat(change) };
      });
      return mock;
    }
  },

  async getMarketHistory(id) {
    try {
      const response = await fetch('https://api.coingecko.com/api/v3/coins/' + id + '/market_chart?vs_currency=usd&days=7');
      if (!response.ok) throw new Error('API error');
      const data = await response.json();
      return data.prices.map(p => p[1]);
    } catch (error) {
      console.warn('CoinGecko history API failed, using mock data');
      const basePrice = Math.random() * 100 + 50;
      return Array.from({ length: 7 }, () => basePrice + (Math.random() * 20 - 10));
    }
  }
};

