  }, []);

  // Save to localStorage on change
  useEffect(() => {
    if (coins.length > 0) {
      localStorage.setItem('crypto_tracker_data', JSON.stringify(coins));
    }
  }, [coins]);

  // Auto-refresh every 30s
  useEffect(() => {
    const interval = setInterval(() => {
      if (coins.length > 0) {
        refreshPrices();
      }
    }, 30000);
    return () => clearInterval(interval);
  }, [coins]);

