        .filter(c => 
          c.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
          c.symbol.toLowerCase().includes(searchQuery.toLowerCase())
        )
        .slice(0, 5);
      setSearchResults(filtered);
      setIsSearching(false);
    }, 300);
    return () => clearTimeout(timer);
