    setIsLoading(true);
    const history = await CoinGeckoService.getMarketHistory(coin.id);
    const prices = await CoinGeckoService.getPrices([coin.id]);
    const priceData = prices[coin.id] || { usd: 0, usd_24h_change: 0 };

    const newCoin = {
      id: coin.id,
      symbol: coin.symbol,
      name: coin.name,
      price: priceData.usd,
      change: priceData.usd_24h_change,
      history: history,
      quantity: 0
    };

    setCoins([...coins, newCoin]);
    setSearchQuery('');
    setSearchResults([]);
    setIsLoading(false);
  };

