const BEGINNER_TIPS = {
  bitcoin: "Bitcoin (BTC) — The 'digital gold'. Most liquid asset in crypto. Good for long-term holding.",
  ethereum: "Ethereum (ETH) — The 'world computer'. Powers most DeFi and NFTs. High utility.",
  solana: "Solana (SOL) — Known for speed and low fees. Great for active trading.",
