        <div style={{ maxHeight: '300px', overflowY: 'auto' }}>
          {loading && <div style={{ textAlign: 'center', color: '#9ca3af', padding: '16px' }}>Searching...</div>}
          {results.map((coin) => (
            <div
              key={coin.id}
              onClick={() => {
                onAdd(coin.id, coin.symbol.toUpperCase(), coin.name);
