              <div>
                <div style={{ color: '#fff', fontWeight: 'bold' }}>{coin.name}</div>
                <div style={{ color: '#9ca3af', fontSize: '14px' }}>{coin.symbol.toUpperCase()}</div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

