      const priceRes = await fetch(`https://api.coingecko.com/api/v3/simple/price?ids=${coin.id}&vs_currencies=usd&include_24h_change=true`);
      const priceData = await priceRes.json();
      const p = priceData[coin.id].usd;
      const c = priceData[coin.id].usd_24h_change;

      setPrice(p);
      setChange24h(c);
      setPulse(true);
