// --- MAIN APP ---
function App() {
  const [coins, setCoins] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [totalValue, setTotalValue] = useState(0);
  const [totalChange, setTotalChange] = useState(0);

  // Load from local storage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        setCoins(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse local storage", e);
      }
    }
  }, []);

  // Save to local storage
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(coins));
  }, [coins]);

  const addCoin = (id, symbol, name) => {
    if (coins.length >= 5) {
      alert("Maximum 5 coins allowed for this micro-tracker.");
      return;
    }
    setCoins([...coins, { id, symbol, name, quantity: 0 }]);
  };

  const removeCoin = (id) => {
    setCoins(coins.filter(c => c.id !== id));
  };

  const updateQuantity = (id, qty) => {
    setCoins(coins.map(c => c.id === id ? { ...c, quantity: qty } : c));
  };

  // Calculate Portfolio Stats
  useEffect(() => {
    if (coins.length === 0) {
      setTotalValue(0);
      setTotalChange(0);
      return;
    }

    let total = 0;
    let totalChangeVal = 0;
    let totalChangePct = 0;

    coins.forEach(coin => {
      // We need to fetch current price to calculate total value
      // In a real app, we'd do this in parallel, but for simplicity we assume `price` state in CoinCard is updated
      // Here we just sum up what we have. 
      // NOTE: For accurate P&L we'd need previous price, but we only store current.
      // Simplified: Just sum current value.
    });

    // Since CoinCard fetches data independently, we can't easily aggregate in App without prop drilling or context.
    // For this demo, we will just show the list. 
