  /**
   * Получает экологические данные
   */
  async getEnvironmentalData(lat, lng) {
    if (CONFIG.DEV.USE_MOCK_DATA) {
      await new Promise(resolve => setTimeout(resolve, CONFIG.DEV.MOCK_DELAY_MS));
    }

    // Интеграция с Open-Meteo для инсоляции
    let sunlightHours = 6;
    try {
      const meteoUrl = `${CONFIG.OPEN_METEO.BASE_URL}/forecast?latitude=${lat}&longitude=${lng}&daily=sunshine_duration&timezone=auto`;
      const response = await fetch(meteoUrl);
      if (response.ok) {
        const data = await response.json();
        sunlightHours = data.daily?.sunshine_duration?.[0] / 3600 || 6;
      }
    } catch (error) {
      console.warn('Failed to fetch sunlight data:', error);
    }

    // Мок-данные для остальных показателей
    const noise = 45 + Math.random() * 30;
    const aqi = 20 + Math.random() * 80;

    return {
      noiseLevelDb: Math.round(noise),
      sunlightHours: Math.round(sunlightHours * 10) / 10,
      airQualityIndex: Math.round(aqi),
      floodRisk: Math.random() > 0.7 ? 'high' : Math.random() > 0.4 ? 'medium' : 'low',
      trafficScore: Math.round(30 + Math.random() * 70),
      walkScore: Math.round(20 + Math.random() * 80),
      transitScore: Math.round(10 + Math.random() * 90)
    };
  }

  /**
   * Рассчитывает Decision Score на основе всех факторов
   */
  calculateDecisionScore(
    marketMetrics,
    zoning,
    environmental,
    propertyType
  ) {
    // Упрощенная логика расчета
    let riskScore = 100;
    let returnScore = 100;
    let stabilityScore = 100;

    const redFlags = [];
    const verdict = [];

    // Факторы риска
    if (environmental.floodRisk === 'high') {
      riskScore -= 30;
      redFlags.push('Высокий риск затопления');
    } else if (environmental.floodRisk === 'medium') {
      riskScore -= 15;
    }

    if (environmental.noiseLevelDb > 70) {
      riskScore -= 20;
      redFlags.push('Высокий уровень шума (>70 dB)');
    }

    if (marketMetrics.daysOnMarket > 90) {
      riskScore -= 25;
      redFlags.push('Длительное время на рынке (>90 дней)');
    }

    // Факторы доходности
    if (marketMetrics.priceTrend5y > 20) {
      returnScore += 15;
      verdict.push('Сильный рост цен за 5 лет (+' + marketMetrics.priceTrend5y.toFixed(1) + '%)');
    } else if (marketMetrics.priceTrend5y < 0) {
      returnScore -= 20;
      redFlags.push('Отрицательная динамика цен');
    }

    if (marketMetrics.capRate && marketMetrics.capRate > 8) {
      returnScore += 20;
      verdict.push('Высокая капитализация (' + marketMetrics.capRate.toFixed(1) + '%)');
    }

    // Факторы стабильности
    if (zoning.densityLimit && zoning.densityLimit > 50) {
      stabilityScore -= 10;
      verdict.push('Высокая плотность застройки может влиять на комфорт');
    }

    if (environmental.sunlightHours < 4) {
      stabilityScore -= 15;
      redFlags.push('Низкая инсоляция (<4 часов в день)');
    }

    // Нормализация
    riskScore = Math.max(0, Math.min(100, riskScore));
    returnScore = Math.max(0, Math.min(100, returnScore));
    stabilityScore = Math.max(0, Math.min(100, stabilityScore));

    const decisionScore = Math.round((riskScore * 0.3 + returnScore * 0.4 + stabilityScore * 0.3));

    // Добавляем общий вердикт
    if (decisionScore >= 80) {
      verdict.unshift('Отличная инвестиционная возможность');
    } else if (decisionScore >= 60) {
      verdict.unshift('Хороший объект с умеренными рисками');
    } else if (decisionScore >= 40) {
      verdict.unshift('Требует дополнительного анализа и осторожности');
    } else {
      verdict.unshift('Высокорисковый объект, рекомендуется избегать');
    }

    return {
      decisionScore,
      riskScore: Math.round(riskScore),
      returnScore: Math.round(returnScore),
      stabilityScore: Math.round(stabilityScore),
      verdict,
      redFlags
    };
  }

  getMockMarketMetrics(propertyType) {
    const basePrice = propertyType === 'commercial' ? 500 : 
                     propertyType === 'industrial' ? 300 : 400;

    const comps = [];
    for (let i = 0; i < 3; i++) {
      comps.push({
        address: `${100 + i * 50} Nearby St, City, ST`,
        distanceMeters: 100 + i * 200,
        price: (basePrice * 1500) * (0.9 + Math.random() * 0.2),
        pricePerSqft: basePrice * (0.9 + Math.random() * 0.2),
        saleDate: `2023-${String(10 - i).padStart(2, '0')}-15`
      });
    }

    return {
      pricePerSqft: basePrice * (0.9 + Math.random() * 0.3),
      rentPerSqft: basePrice * 0.01 * (0.8 + Math.random() * 0.4),
      priceTrend5y: 5 + Math.random() * 25,
      rentTrend5y: 3 + Math.random() * 15,
      daysOnMarket: Math.round(30 + Math.random() * 90),
      capRate: propertyType === 'commercial' ? 5 + Math.random() * 5 : undefined,
      noi: propertyType === 'commercial' ? 50000 + Math.random() * 150000 : undefined,
      comparables: comps
    };
  }
}

