/**
 * Основной сервис анализа недвижимости Propa AI
 * Интегрирует геоданные, анализ изображений, правила и выдаёт Flash-вердикт
 */


export type UserGoal = 'rent' | 'buy' | 'invest' | 'business';
export type InputType = 'photo' | 'geo' | 'address' | 'link' | 'text';

export interface PropertyAnalysisInput {
  type: InputType;
  data: {
    photoUrl?: string;
    coordinates?: { lat: number; lon: number };
    address?: string;
    link?: string;
    question?: string;
  };
  userGoal: UserGoal;
  userId?: string;
}

export interface FlashVerdict {
  score: number; // 0-100
  zone: 'green' | 'yellow' | 'red';
  sub_scores: {
    risk: number; // 0-100, lower is better
    return: number; // 0-100, higher is better
    stability: number; // 0-100, higher is better
  };
  reasons: Array<{
    text: string;
    time_horizon: 'immediate' | 'short_term' | 'long_term';
    impact: 'high' | 'medium' | 'low';
  }>;
  evidence: Array<{
    fact: string;
    source: string;
    relevance: 'high' | 'medium' | 'low';
  }>;
  red_flags: string[];
  next_steps: string[];
  confidence: 'low' | 'medium' | 'high';
  processing_time_ms: number;
}

class PropertyAnalysisService {
  /**
   * Основной метод анализа: принимает любую зацепку, возвращает Flash-вердикт
   */
  async analyzeProperty(input: PropertyAnalysisInput): Promise<FlashVerdict> {
    const startTime = Date.now();

    try {
      // 1. Получаем геоданные (если есть координаты/адрес)
      let geoAnalysis: GeoAnalysis | null = null;
      if (input.data.coordinates) {
        geoAnalysis = await geoService.analyzeLocation(input.data.coordinates);
      } else if (input.data.address) {
        geoAnalysis = await geoService.analyzeLocation(input.data.address);
      }

      // 2. Анализ изображения (если есть фото)
      let visionAnalysis: VisionAnalysis | null = null;
      if (input.data.photoUrl) {
        visionAnalysis = await visionAnalysisService.analyzeImage(input.data.photoUrl);
      }

      // 3. Применяем rule-switch по штату
      const stateRules = geoAnalysis?.location?.state ? 
        geoService.getStateRules(geoAnalysis.location.state) : null;

      // 4. Генерируем скоринг на основе всех данных
      const score = this.calculateScore(geoAnalysis, visionAnalysis, stateRules, input.userGoal);

      // 5. Формируем причины и доказательства
      const reasons = this.generateReasons(geoAnalysis, visionAnalysis, stateRules, input.userGoal);
      const evidence = this.generateEvidence(geoAnalysis, visionAnalysis);
      const redFlags = this.extractRedFlags(geoAnalysis, visionAnalysis, stateRules);
      const nextSteps = this.generateNextSteps(input.userGoal, redFlags, geoAnalysis);

      // 6. Определяем confidence
      const confidence = this.determineConfidence(geoAnalysis, visionAnalysis);

      const processingTime = Date.now() - startTime;

      return {
        score,
        zone: score >= 70 ? 'green' : score >= 40 ? 'yellow' : 'red',
        sub_scores: {
          risk: this.calculateRiskScore(geoAnalysis, visionAnalysis, stateRules),
          return: this.calculateReturnScore(geoAnalysis, input.userGoal),
          stability: this.calculateStabilityScore(geoAnalysis, stateRules)
        },
        reasons,
        evidence,
        red_flags: redFlags,
        next_steps: nextSteps,
        confidence,
        processing_time_ms: processingTime
      };
    } catch (error) {
      console.error('Property analysis failed:', error);
      const processingTime = Date.now() - startTime;

      // Fallback вердикт при ошибке
      return {
        score: 50,
        zone: 'yellow',
        sub_scores: { risk: 60, return: 50, stability: 50 },
        reasons: [{
          text: 'Недостаточно данных для полного анализа',
          time_horizon: 'immediate',
          impact: 'medium'
        }],
        evidence: [{
          fact: 'Анализ выполнен с ограниченными данными',
          source: 'Propa AI',
          relevance: 'high'
        }],
        red_flags: ['Не удалось получить полную информацию об объекте'],
        next_steps: ['Попробуйте загрузить фото объекта', 'Уточните адрес', 'Проверьте вручную ключевые документы'],
        confidence: 'low',
        processing_time_ms: processingTime
      };
    }
  }

  /**
   * Основной скоринг 0-100
   */
  private calculateScore(
    geo: GeoAnalysis | null,
    vision: VisionAnalysis | null,
    stateRules: Record<string, boolean> | null,
    goal: UserGoal
  ): number {
    let score = 50; // Базовая середина

    // Гео-факторы
    if (geo) {
      // Важность места
      if (geo.location?.importance && geo.location.importance > 0.7) score += 10;
      if (geo.location?.importance && geo.location.importance < 0.3) score -= 10;

      // Риски
      if (geo.risks && geo.risks.length > 0) score -= geo.risks.length * 5;
      if (geo.opportunities && geo.opportunities.length > 0) score += geo.opportunities.length * 3;

      // Инфраструктура
      if (geo.nearby_amenities) {
        if (geo.nearby_amenities.schools >= 3) score += 5;
        if (geo.nearby_amenities.parks >= 2) score += 3;
        if (geo.nearby_amenities.transit >= 1) score += 4;
        if (geo.nearby_amenities.shops >= 4) score += 3;
      }
    }

    // Vision факторы
    if (vision) {
      if (vision.condition === 'excellent') score += 8;
      if (vision.condition === 'good') score += 4;
      if (vision.condition === 'poor') score -= 10;

      if (vision.potential_issues && vision.potential_issues.length > 0) {
        score -= vision.potential_issues.length * 7;
      }

      if (vision.features && vision.features.length >= 3) score += 5;
    }

    // Правила штата
    if (stateRules) {
      if (stateRules.zoning_strict) score -= 5; // Строгое зонирование может ограничивать
      if (stateRules.flood_risk) score -= 8;
      if (stateRules.earthquake_risk) score -= 6;
      if (stateRules.hurricane_risk) score -= 7;
    }

    // Корректировка по цели
    if (goal === 'rent') {
      // Для аренды важна стабильность и инфраструктура
      if (geo?.nearby_amenities?.transit) score += 3;
    } else if (goal === 'invest') {
      // Для инвестиций важны возможности роста
      if (stateRules && !stateRules.zoning_strict) score += 5;
    } else if (goal === 'business') {
      // Для бизнеса важна проходимость и видимость
      if (geo?.location?.importance && geo.location.importance > 0.5) score += 7;
    }

    // Ограничиваем 0-100
    return Math.max(0, Math.min(100, Math.round(score)));
  }

  private calculateRiskScore(
    geo: GeoAnalysis | null,
    vision: VisionAnalysis | null,
    stateRules: Record<string, boolean> | null
  ): number {
    let risk = 50;

    if (geo?.risks) risk += geo.risks.length * 8;
    if (vision?.potential_issues) risk += vision.potential_issues.length * 10;
    if (stateRules) {
      if (stateRules.flood_risk) risk += 15;
      if (stateRules.earthquake_risk) risk += 12;
      if (stateRules.hurricane_risk) risk += 14;
    }

    return Math.max(0, Math.min(100, risk));
  }

  private calculateReturnScore(geo: GeoAnalysis | null, goal: UserGoal): number {
    let returnScore = 50;

    if (geo) {
      if (geo.location?.importance && geo.location.importance > 0.7) returnScore += 15;
      if (geo.opportunities) returnScore += geo.opportunities.length * 6;
      if (geo.nearby_amenities) {
        returnScore += Math.min(geo.nearby_amenities.schools * 3, 12);
        returnScore += Math.min(geo.nearby_amenities.shops * 2, 8);
      }
    }

    // Для инвестиций выше потенциал возврата
    if (goal === 'invest') returnScore += 10;

    return Math.max(0, Math.min(100, returnScore));
  }

  private calculateStabilityScore(
    geo: GeoAnalysis | null,
    stateRules: Record<string, boolean> | null
  ): number {
    let stability = 50;

    if (geo) {
      // Стабильные районы обычно имеют среднюю-высокую важность
      if (geo.location?.importance && geo.location.importance >= 0.4 && geo.location.importance <= 0.8) {
        stability += 10;
      }
      if (geo.nearby_amenities?.schools >= 2) stability += 5;
      if (geo.nearby_amenities?.parks >= 2) stability += 3;
    }

    if (stateRules) {
      if (stateRules.zoning_strict) stability += 5; // Строгое зонирование = стабильность правил
      if (stateRules.flood_risk) stability -= 12;
      if (stateRules.earthquake_risk) stability -= 10;
    }

    return Math.max(0, Math.min(100, stability));
  }

  private generateReasons(
    geo: GeoAnalysis | null,
    vision: VisionAnalysis | null,
    stateRules: Record<string, boolean> | null,
    goal: UserGoal
  ): Array<{text: string; time_horizon: 'immediate' | 'short_term' | 'long_term'; impact: 'high' | 'medium' | 'low'}> {
    const reasons = [];

    if (geo) {
      if (geo.location?.importance && geo.location.importance > 0.7) {
        reasons.push({
          text: 'Высокая значимость локации в городе',
          time_horizon: 'long_term',
          impact: 'high'
        });
      }

      if (geo.risks && geo.risks.length > 0) {
        geo.risks.forEach(risk => {
          reasons.push({
            text: risk,
            time_horizon: risk.includes('риск') ? 'immediate' : 'long_term',
            impact: 'high'
          });
        });
      }

      if (geo.nearby_amenities) {
        if (geo.nearby_amenities.schools >= 3) {
          reasons.push({
            text: 'Хорошая доступность школ',
            time_horizon: 'long_term',
            impact: 'medium'
          });
        }
        if (geo.nearby_amenities.transit >= 1) {
          reasons.push({
            text: 'Есть общественный транспорт',
            time_horizon: 'immediate',
            impact: goal === 'rent' ? 'high' : 'medium'
          });
        }
      }
    }

    if (vision) {
      if (vision.condition === 'excellent') {
        reasons.push({
          text: 'Отличное состояние объекта',
          time_horizon: 'immediate',
          impact: 'high'
        });
      } else if (vision.condition === 'poor') {
        reasons.push({
          text: 'Плохое состояние объекта требует вложений',
          time_horizon: 'short_term',
          impact: 'high'
        });
      }

      if (vision.features && vision.features.length >= 3) {
        reasons.push({
          text: `Объект имеет ${vision.features.length} дополнительных преимуществ`,
          time_horizon: 'immediate',
          impact: 'medium'
        });
      }
    }

    if (stateRules) {
      if (stateRules.zoning_strict) {
        reasons.push({
          text: 'Строгое зонирование ограничивает изменения',
          time_horizon: 'long_term',
          impact: 'medium'
        });
      }
    }

    // Добавляем причину по цели если их мало
    if (reasons.length < 3) {
      const goalReasons = {
        rent: 'Подходит для аренды с учётом местного спроса',
        buy: 'Стабильный район для проживания',
        invest: 'Потенциал для роста стоимости',
        business: 'Локация подходит для коммерческой активности'
      };

      reasons.push({
        text: goalReasons[goal],
        time_horizon: 'long_term',
        impact: 'medium'
      });
    }

    return reasons.slice(0, 5); // Максимум 5 причин
  }

  private generateEvidence(
    geo: GeoAnalysis | null,
    vision: VisionAnalysis | null
  ): Array<{fact: string; source: string; relevance: 'high' | 'medium' | 'low'}> {
    const evidence = [];

    if (geo?.location) {
      evidence.push({
        fact: `Локация: ${geo.location.city}, ${geo.location.state}`,
        source: 'Geoapify/OpenStreetMap',
        relevance: 'high'
      });
    }

    if (geo?.nearby_amenities) {
      evidence.push({
        fact: `В районе: ${geo.nearby_amenities.schools} школ, ${geo.nearby_amenities.parks} парков, ${geo.nearby_amenities.shops} магазинов`,
        source: 'OpenStreetMap данные',
        relevance: 'medium'
      });
    }

    if (vision) {
      evidence.push({
        fact: `Тип объекта: ${vision.property_type}, состояние: ${vision.condition}`,
        source: 'OpenAI Vision анализ',
        relevance: 'high'
      });

      if (vision.features && vision.features.length > 0) {
        evidence.push({
          fact: `Обнаружены особенности: ${vision.features.slice(0, 3).join(', ')}`,
          source: 'Анализ изображения',
          relevance: 'medium'
        });
      }
    }

    // Минимальное доказательство если данных нет
    if (evidence.length === 0) {
      evidence.push({
        fact: 'Анализ основан на ограниченных доступных данных',
        source: 'Propa AI',
        relevance: 'high'
      });
    }

    return evidence.slice(0, 3); // Максимум 3 доказательства
  }

  private extractRedFlags(
    geo: GeoAnalysis | null,
    vision: VisionAnalysis | null,
    stateRules: Record<string, boolean> | null
  ): string[] {
    const flags = [];

    if (vision?.potential_issues && vision.potential_issues.length > 0) {
      vision.potential_issues.forEach(issue => {
        flags.push(`Видимая проблема: ${issue}`);
      });
    }

    if (stateRules) {
      if (stateRules.flood_risk) flags.push('Район подвержен риску наводнений');
      if (stateRules.earthquake_risk) flags.push('Сейсмическая активность в регионе');
      if (stateRules.hurricane_risk) flags.push('Риск ураганов');
    }

    if (vision?.condition === 'poor') {
      flags.push('Объект в плохом состоянии требует значительных вложений');
    }

    if (geo && !geo.location?.city) {
      flags.push('Не удалось точно определить локацию');
    }

    return flags.slice(0, 5); // Максимум 5 красных флагов
  }

  private generateNextSteps(
    goal: UserGoal,
    redFlags: string[],
    geo: GeoAnalysis | null
  ): string[] {
    const steps = [];

    // Общие шаги
    steps.push('Проверить официальные документы на объект');
    steps.push('Уточнить стоимость страховки для данного типа недвижимости');

    // Шаги по цели
    if (goal === 'rent') {
      steps.push('Проверить средние цены аренды в районе за последние 6 месяцев');
      steps.push('Опросить соседей о качестве управления зданием');
    } else if (goal === 'buy') {
      steps.push('Заказать профессиональную инспекцию объекта');
      steps.push('Проверить историю цен на аналогичные объекты в районе');
    } else if (goal === 'invest') {
      steps.push('Проанализировать динамику арендных ставок в районе');
      steps.push('Проверить планы развития района на ближайшие 5 лет');
    } else if (goal === 'business') {
      steps.push('Оценить пешеходный и автомобильный трафик в разное время суток');
      steps.push('Проверить наличие конкурентов в радиусе 500 метров');
    }

    // Шаги по красным флагам
    if (redFlags.length > 0) {
      if (redFlags.some(f => f.includes('наводнени'))) {
        steps.push('Запросить отчёт о наводнениях (FEMA Flood Map)');
      }
      if (redFlags.some(f => f.includes('сейсми'))) {
        steps.push('Проверить сейсмические нормы строительства в штате');
      }
    }

    // Шаги по геоданным
    if (geo?.location?.state) {
      steps.push(`Проверить местные правила зонирования в ${geo.location.state}`);
    }

    return steps.slice(0, 5); // Максимум 5 следующих шагов
  }

  private determineConfidence(
    geo: GeoAnalysis | null,
    vision: VisionAnalysis | null
  ): 'low' | 'medium' | 'high' {
    let confidencePoints = 0;

    if (geo?.location?.city) confidencePoints += 2;
    if (geo?.location?.importance !== undefined) confidencePoints += 1;
    if (geo?.nearby_amenities) confidencePoints += 1;
    if (vision?.property_type && vision.property_type !== 'unknown') confidencePoints += 2;
    if (vision?.condition && vision.condition !== 'unknown') confidencePoints += 1;
    if (vision?.confidence && vision.confidence > 0.7) confidencePoints += 1;

    if (confidencePoints >= 6) return 'high';
    if (confidencePoints >= 3) return 'medium';
    return 'low';
  }
}

